from base.service import BaseServicefrom entities.container import Containerfrom repositories.container import ContainerRepositoryfrom sqlalchemy.ext.asyncio import AsyncSessionfrom entities.container import ContainerTypefrom utils.container import ContainerSearchParamsfrom helpers.search import Paginationclass ContainerService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def search_container(            self, type_: ContainerType,            search: ContainerSearchParams,            pagination: Pagination    ) -> list[FullContainerDTO]:        containers = await self.repository.search(            type_=type_, **pagination.dict(), **search.dict()        )        return containers